331	\begin{definition}[Win predicate of the Pauli basis test]\label{def:pauli-win-predicate}
332		\uses{def:pauli-question-distribution, def:ld-win-predicate, def:ms-game, def:indicator-vector, def:admissible}
333		Fix an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}) and let $M = 2^m$. Answers in the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
334		% The paper's format table writes the line contents loosely as (u_W, s) and (u_W, s, v);
335		% by the sampling procedure the actual contents are the canonical pairs (u_0, s) and
336		% triples (u_0, s, v') with v' = pi_{i-1}(v). We state the canonical form.
337		\begin{itemize}
338			\item $(\mathsf{Point},W)$: content $y \in \F_q^m$; answer an element of $\F_q$.
339			\item $(\mathsf{ALine},W)$: content $(u_0, s) \in \F_q^m \times \F_q$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $d$.
340			\item $(\mathsf{DLine},W)$: content $(u_0, s, v') \in \F_q^m \times \F_q \times \F_q^m$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $md$.
341			\item $\mathsf{Pair}$: content $\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times \F_q^2$; answer $(\beta_X, \beta_Z) \in \F_2^2$.
342			\item $(\mathsf{Pair},W)$: content $\omega$ as above; answer an element of $\F_2$.
343			\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
344			\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
345			\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
346		\end{itemize}
347		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
348		\begin{equation}
349			\label{eq:gamma-value}
350			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
351		\end{equation}
352		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
353		\begin{enumerate}
354			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
355			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
356			\begin{enumerate}
357				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
358				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
359			\end{enumerate}
360			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
361			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
362			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
363			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
364			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
365		\end{enumerate}
366		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
367	\end{definition}
368	
369	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
370	
371	\begin{lemma}[Completeness of the Pauli basis test]\label{lem:pauli-completeness}
372		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:spcc, def:tensor-product-value}
373		For every admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}), the Pauli basis test $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ has a value-$1$ SPCC strategy.
374	\end{lemma}
375	\begin{proof}
376		\uses{thm:ms-from-ac, def:pauli-win-predicate, def:bracket, def:consistent-measurement, def:EPR, def:indicator-vector, lem:pauli-observable-expansion, lem:twisted-commutation}
377		The strategy uses the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot M} \ot \ket{\mathrm{EPR}_2}$ with $M = 2^m$. On a question $((\mathsf{Point},W), y)$ a player measures the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ and reports $g_h(y)$; on $((\mathsf{ALine},W), \ell)$ or $((\mathsf{DLine},W), \ell)$ they report the restriction of $g_h$ to the line $\ell$, expressed as a univariate polynomial through the canonical parameterization of $\ell$; and on $(\mathsf{Pauli},W)$ they report $h$ itself --- in the bracket notation of Definition~\ref{def:bracket}, these measurements are $\tau^W_{[g_\cdot(y) = a]} \ot I$, $\tau^W_{[(g_\cdot)|_\ell = f]} \ot I$, and $\tau^W_a \ot I$. For a content $\omega = (u_X, u_Z, r_X, r_Z)$, consider the two binary measurements $A_b = \tau^X_{[\tr(g_\cdot(u_X)\, r_X) = b]} \ot I$ and $B_b = \tau^Z_{[\tr(g_\cdot(u_Z)\, r_Z) = b]} \ot I$. Since $g_h(u) = h \cdot \mathrm{ind}_m(u)$ (Chapter~\ref{chap:qpbt-algebra}), the relation between the Pauli projections and observables gives $\mathcal O_A = A_0 - A_1 = \tau^X(\mathrm{ind}_m(u_X)\, r_X) \ot I$ and $\mathcal O_B = \tau^Z(\mathrm{ind}_m(u_Z)\, r_Z) \ot I$, and the twisted commutation relation yields
378		\[
379			\mathcal O_A \mathcal O_B = (-1)^\gamma\, \mathcal O_B \mathcal O_A
380		\]
381		with $\gamma$ as in Equation~\eqref{eq:gamma-value}: the two measurements commute when $\gamma = 0$ and anticommute when $\gamma = 1$. If $\gamma = 0$, define $E^{\mathsf{Pair},\omega}_{\beta_X,\beta_Z} = A_{\beta_X} B_{\beta_Z}$ and $E^{(\mathsf{Pair},X),\omega}_a = A_a$, $E^{(\mathsf{Pair},Z),\omega}_a = B_a$, and let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be trivial (identity on the all-zeros outcome). If $\gamma = 1$, let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be those produced by Theorem~\ref{thm:ms-from-ac} from the anticommuting consistent pair $(A, B)$, acting on the auxiliary $\ket{\mathrm{EPR}_2}$ factor, and let the $\mathsf{Pair}$ measurements be trivial. The strategy is symmetric and projective by construction; every measurement is either a post-processed Pauli basis measurement, a measurement supplied by Theorem~\ref{thm:ms-from-ac}, or (in the $\gamma = 0$ case) a product of two commuting consistent measurements, so the strategy is consistent, and commutativity along every edge of $G^{\mathrm{pauli}}$ is checked case by case --- for instance, $(\mathsf{Point},X)$ and $\mathsf{Variable}_1$ commute because both are $X$-basis measurements. Consistency and projectivity give the consistency checks with certainty, and the low-degree checks pass because the answers agree with the strategy determined by the polynomial $g_h$ in the classical game. For the remaining checks: when $\gamma = 0$ the commutation check passes by construction, and when $\gamma = 1$ the Magic Square check passes by Theorem~\ref{thm:ms-from-ac}; the consistency checks 5 and 7 pass with certainty because $\tau^W_{[\tr(g_\cdot(y)\, r_W) = \cdot]} \ot I$ coincides with $E^{(\mathsf{Pair},W),\omega}$, respectively with the embedded $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ measurements of Theorem~\ref{thm:ms-from-ac} (item~3 there). Hence the strategy has value $1$.
382	\end{proof}
383	
384	We now state the main soundness property of the Pauli basis test; the statement is an adaptation of the self-testing theorem of~\cite{Natarajan2018NEEXP} (Theorem~6.4 there). Unlike Theorem~\ref{lem:ld-soundness}, no projectivity assumption is made on the strategy.
385	
386	\begin{theorem}[Soundness of the Pauli basis test]\label{thm:pauli}
387		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, lem:pauli-observable-expansion, def:povm-distance}
388		There exists a function
389		\[
390			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
391		\]
392		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^q)^{\ot M}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
393		\begin{enumerate}
394			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
395			% The paper here has the typo "phi_alice \ot phi_B"; both maps are the isometries above.
396			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
397			\begin{align*}
398				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\tau^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
399				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\tau^W_u)_{\mathrm B''}\;,
400			\end{align*}
401			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$.
402		\end{enumerate}
403	\end{theorem}
404	
405	The proof of Theorem~\ref{thm:pauli} is the adaptation, to low individual degree, of the analysis of the quantum low-degree test of Natarajan and Vidick; it is developed in Chapters~\ref{chap:qpbt-observables} and~\ref{chap:qpbt-combining} and concluded in Chapter~\ref{chap:qpbt-extraction}, where the argument is complete only modulo the unresolved divisibility obligation documented in \cite{gap:qpbt_ld-dimension-divisibility}. It relies on the classical soundness theorem (Theorem~\ref{lem:ld-soundness}) and on the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}).
406	
407	The strategies appearing in Lemma~\ref{lem:pauli-completeness} and in the conclusion of Theorem~\ref{thm:pauli} are phrased in terms of qudit Pauli measurements and maximally entangled states of $q$-dimensional qudits. For the intended application it is more convenient to work with qubits: since the field sizes $q$ used here are powers of $2$, the conclusions can be restated in terms of qubit EPR pairs and qubit Pauli measurements.
